using System.Numerics;
using System.Text.Json;
namespace CsEsp;
// Local read-only static geometry queries. Hits alone do not establish penetration or damage.
internal sealed class CollisionGeometry
{
 // Thickness/ExitPoint are clipped to the query segment. Only HasPhysicalExit establishes
 // an outgoing material boundary; otherwise ExitNormal is zero. EndsInside means strictly
 // interior to every halfspace (1e-6 tolerance); StartsInside retains boundary-inclusive semantics.
 internal sealed record HullInterval(double EntryT,double ExitT,double Thickness,Vector3 EntryPoint,Vector3 ExitPoint,Vector3 EntryNormal,Vector3 ExitNormal,bool StartsInside,bool EndsInside,bool HasPhysicalExit,bool IsTangent,int HullIndex,uint SurfaceHash,int CollisionAttributeIndex,JsonElement CollisionAttributes);
 internal sealed record MeshHit(double T,Vector3 Point,Vector3 Normal,bool FrontFacing,uint SurfaceHash,int CollisionAttributeIndex,JsonElement CollisionAttributes,int MeshIndex,int TriangleIndex);
 internal sealed record TraceResult(IReadOnlyList<HullInterval> HullIntervals,IReadOnlyList<MeshHit> MeshHits,int CandidateTests){public bool BallisticsAvailable=>false;public bool MeshClosureKnown=>false;}
 readonly record struct Box(Vector3 Min,Vector3 Max){public Vector3 Center=>(Min+Max)*.5f;public static Box Union(Box a,Box b)=>new(Vector3.Min(a.Min,b.Min),Vector3.Max(a.Max,b.Max));}
 sealed record Hull(Box Bounds,Vector4[] Planes,uint SurfaceHash,int Attribute);
 readonly record struct Triangle(Vector3 A,Vector3 B,Vector3 C,Vector3 Normal,uint SurfaceHash,int Attribute,int MeshIndex,int TriangleIndex);
 readonly record struct Primitive(Box Bounds,int Index,bool IsHull);
 sealed record Node(Box Bounds,int Start,int Count,int Left,int Right);
 readonly Hull[] hulls;readonly Triangle[] triangles;readonly JsonElement[] attributes;readonly Primitive[] primitives;readonly List<Node> nodes=new();
 public string Map {get;}public int HullCount=>hulls.Length;public int TriangleCount=>triangles.Length;public bool BallisticsAvailable=>false;
 CollisionGeometry(string map,Hull[] hulls,Triangle[] triangles,JsonElement[] attributes){Map=map;this.hulls=hulls;this.triangles=triangles;this.attributes=attributes;primitives=new Primitive[hulls.Length+triangles.Length];for(int i=0;i<hulls.Length;i++)primitives[i]=new(hulls[i].Bounds,i,true);for(int i=0;i<triangles.Length;i++){var t=triangles[i];primitives[hulls.Length+i]=new(new(Vector3.Min(t.A,Vector3.Min(t.B,t.C)),Vector3.Max(t.A,Vector3.Max(t.B,t.C))),i,false);}if(primitives.Length>0)Build(0,primitives.Length);}
 static InvalidDataException Invalid(string message)=>new("Invalid collision geometry: "+message);
 static bool Finite(Vector3 v)=>float.IsFinite(v.X)&&float.IsFinite(v.Y)&&float.IsFinite(v.Z)&&Math.Abs(v.X)<=1e9&&Math.Abs(v.Y)<=1e9&&Math.Abs(v.Z)<=1e9;
 static Vector3 Vec(JsonElement value){if(value.ValueKind!=JsonValueKind.Array||value.GetArrayLength()!=3)throw Invalid("vector shape");var v=new Vector3(value[0].GetSingle(),value[1].GetSingle(),value[2].GetSingle());if(!Finite(v))throw Invalid("nonfinite vector");return v;}
 static Box Bounds(JsonElement value){var min=Vec(value.GetProperty("min"));var max=Vec(value.GetProperty("max"));if(min.X>max.X||min.Y>max.Y||min.Z>max.Z)throw Invalid("inverted bounds");return new(min,max);}
 static bool Contains(Box b,Vector3 v,float epsilon=.051f)=>v.X>=b.Min.X-epsilon&&v.Y>=b.Min.Y-epsilon&&v.Z>=b.Min.Z-epsilon&&v.X<=b.Max.X+epsilon&&v.Y<=b.Max.Y+epsilon&&v.Z<=b.Max.Z+epsilon;
 static void ValidateJson(JsonElement v,ref int budget){if(--budget<0)throw Invalid("structural limit");if(v.ValueKind==JsonValueKind.Object){var names=new HashSet<string>(StringComparer.Ordinal);foreach(var p in v.EnumerateObject()){if(!names.Add(p.Name)||p.Name is "__proto__" or "prototype" or "constructor")throw Invalid("duplicate or unsafe key");ValidateJson(p.Value,ref budget);}}else if(v.ValueKind==JsonValueKind.Array)foreach(var e in v.EnumerateArray())ValidateJson(e,ref budget);}
 // A finite AABB is not evidence that halfspaces are bounded: validate the actual polytope.
 readonly record struct D3(double X,double Y,double Z){public static D3 operator +(D3 a,D3 b)=>new(a.X+b.X,a.Y+b.Y,a.Z+b.Z);public static D3 operator *(D3 a,double b)=>new(a.X*b,a.Y*b,a.Z*b);public double Length=>Math.Sqrt(X*X+Y*Y+Z*Z);public Vector3 Float=>new((float)X,(float)Y,(float)Z);}
 static D3 Cross(D3 a,D3 b)=>new(a.Y*b.Z-a.Z*b.Y,a.Z*b.X-a.X*b.Z,a.X*b.Y-a.Y*b.X);
 static double Dot(D3 a,D3 b)=>a.X*b.X+a.Y*b.Y+a.Z*b.Z;
 static Box ValidateHull(Box bounds,Vector4[] planes,ref long work){
 if(planes.Length>128)throw Invalid("hull plane complexity");
 var normals=planes.Select(p=>new D3(p.X,p.Y,p.Z)).ToArray();bool rankThree=false;var vertices=new List<Vector3>();
 for(int i=0;i<planes.Length;i++)for(int j=i+1;j<planes.Length;j++){
 var cross=Cross(normals[i],normals[j]);double length=cross.Length;
 if(length<1e-7&&Dot(normals[i],normals[j])>0&&Math.Abs(planes[i].W-planes[j].W)<1e-4)throw Invalid("duplicate hull plane");
 if(length>1e-9){var direction=cross*(1/length);foreach(double sign in new[]{-1d,1d}){bool ray=true;foreach(var normal in normals){if(++work>50000000)throw Invalid("hull validation work limit");if(Dot(normal,direction)*sign>1e-8){ray=false;break;}}if(ray)throw Invalid("unbounded hull halfspaces");}}
 for(int k=j+1;k<planes.Length;k++){if(++work>50000000)throw Invalid("hull validation work limit");double determinant=Dot(cross,normals[k]);if(Math.Abs(determinant)<1e-9)continue;rankThree=true;var point=(Cross(normals[j],normals[k])*planes[i].W+Cross(normals[k],normals[i])*planes[j].W+cross*planes[k].W)*(1/determinant);if(!double.IsFinite(point.X)||!double.IsFinite(point.Y)||!double.IsFinite(point.Z)||point.Length>2e9)continue;bool feasible=true;for(int q=0;q<planes.Length;q++){if(++work>50000000)throw Invalid("hull validation work limit");if(Dot(normals[q],point)-planes[q].W>1e-4){feasible=false;break;}}if(feasible){var v=point.Float;if(!Contains(bounds,v,.1f))throw Invalid("hull bounds do not enclose halfspaces");if(!vertices.Any(other=>Vector3.DistanceSquared(other,v)<1e-10f))vertices.Add(v);}}
 }
 if(!rankThree||vertices.Count<4)throw Invalid("infeasible or lower-dimensional hull");
 var min=vertices.Aggregate(Vector3.Min);var max=vertices.Aggregate(Vector3.Max);if(Vector3.Distance(min,bounds.Min)>.18f||Vector3.Distance(max,bounds.Max)>.18f)throw Invalid("hull bounds disagree with halfspaces");
 // Reject flat polytopes even if four redundant intersections were found.
 bool volume=false;var origin=vertices[0];for(int i=1;i<vertices.Count&&!volume;i++)for(int j=i+1;j<vertices.Count&&!volume;j++){var cross=Vector3.Cross(vertices[i]-origin,vertices[j]-origin);for(int k=j+1;k<vertices.Count;k++)if(Math.Abs(Dot(cross,vertices[k]-origin))>1e-9){volume=true;break;}}if(!volume)throw Invalid("zero-volume hull");return new(min-new Vector3(.0001f),max+new Vector3(.0001f));
 }
 public static CollisionGeometry Load(string path){try{using var file=new FileStream(path,FileMode.Open,FileAccess.Read,FileShare.Read);if(file.Length is <2 or >67108864)throw Invalid("file size");using var document=JsonDocument.Parse(file,new JsonDocumentOptions{MaxDepth=32,AllowTrailingCommas=false,CommentHandling=JsonCommentHandling.Disallow});var root=document.RootElement;int budget=6000000;ValidateJson(root,ref budget);if(root.GetProperty("format").GetInt32()!=1||root.GetProperty("ballisticsAvailable").GetBoolean())throw Invalid("format or unsupported ballistics claim");string map=root.GetProperty("map").GetString()??"";if(map.Length is <4 or >64||!System.Text.RegularExpressions.Regex.IsMatch(map,"^de_[a-z0-9_]+$"))throw Invalid("map name");var hashJson=root.GetProperty("surfaceHashes");if(hashJson.GetArrayLength()>10000)throw Invalid("surface table limit");uint[] hashes=hashJson.EnumerateArray().Select(x=>x.GetUInt32()).ToArray();var attrJson=root.GetProperty("collisionAttributes");if(attrJson.GetArrayLength()>10000)throw Invalid("attribute table limit");var attrs=attrJson.EnumerateArray().Select(x=>{if(x.ValueKind!=JsonValueKind.Object)throw Invalid("attribute shape");return x.Clone();}).ToArray();int Attribute(JsonElement record){int i=record.GetProperty("collisionAttributeIndex").GetInt32();if((uint)i>=attrs.Length)throw Invalid("collision attribute index");return i;}uint Surface(int index){if((uint)index>=hashes.Length)throw Invalid("surface index");return hashes[index];}
 var hullJson=root.GetProperty("hulls");if(hullJson.GetArrayLength()>100000)throw Invalid("hull count limit");var loadedHulls=new List<Hull>();int planeCount=0;long hullValidationWork=0;foreach(var h in hullJson.EnumerateArray()){Box b=Bounds(h.GetProperty("bounds"));var planeJson=h.GetProperty("planes");int count=planeJson.GetArrayLength();if(count is <4 or >10000||(planeCount+=count)>1000000)throw Invalid("plane limit");var planes=new Vector4[count];int n=0;foreach(var p in planeJson.EnumerateArray()){if(p.GetArrayLength()!=4)throw Invalid("plane shape");var normal=new Vector3(p[0].GetSingle(),p[1].GetSingle(),p[2].GetSingle());float distance=p[3].GetSingle();if(!Finite(normal)||Math.Abs(normal.Length()-1)>.01||!float.IsFinite(distance)||Math.Abs(distance)>1e9)throw Invalid("plane normal or distance");planes[n++]=new(normal,distance);}b=ValidateHull(b,planes,ref hullValidationWork);int surfaceIndex=h.GetProperty("surfaceIndex").GetInt32();uint surface=Surface(surfaceIndex);if(surface!=h.GetProperty("surfaceHash").GetUInt32())throw Invalid("surface hash mismatch");loadedHulls.Add(new(b,planes,surface,Attribute(h)));}
 var meshJson=root.GetProperty("meshes");if(meshJson.GetArrayLength()>10000)throw Invalid("mesh count limit");var loadedTriangles=new List<Triangle>();int vertexCount=0,meshIndex=0;foreach(var mesh in meshJson.EnumerateArray()){Box bounds=Bounds(mesh.GetProperty("bounds"));var verticesJson=mesh.GetProperty("vertices");int count=verticesJson.GetArrayLength();if(count is <3 or >1000000||(vertexCount+=count)>2000000)throw Invalid("vertex limit");var vertices=verticesJson.EnumerateArray().Select(Vec).ToArray();if(vertices.Any(v=>!Contains(bounds,v)))throw Invalid("mesh vertex outside bounds");int attribute=Attribute(mesh);var triangleJson=mesh.GetProperty("triangles");var surfaceJson=mesh.GetProperty("surfaceIndices");if(triangleJson.GetArrayLength()!=surfaceJson.GetArrayLength()||loadedTriangles.Count+triangleJson.GetArrayLength()>2000000)throw Invalid("triangle material mapping or count");int triangleIndex=0;foreach(var t in triangleJson.EnumerateArray()){if(t.GetArrayLength()!=3)throw Invalid("triangle shape");int a=t[0].GetInt32(),b=t[1].GetInt32(),c=t[2].GetInt32();if((uint)a>=vertices.Length||(uint)b>=vertices.Length||(uint)c>=vertices.Length)throw Invalid("triangle vertex index");uint surface=Surface(surfaceJson[triangleIndex++].GetInt32());var cross=Vector3.Cross(vertices[b]-vertices[a],vertices[c]-vertices[a]);if(!Finite(cross)||cross.LengthSquared()<1e-16f)throw Invalid("degenerate triangle");loadedTriangles.Add(new(vertices[a],vertices[b],vertices[c],Vector3.Normalize(cross),surface,attribute,meshIndex,triangleIndex-1));}meshIndex++;}
 var counts=root.GetProperty("counts");foreach(var (name,actual)in new(string,int)[]{("hulls",loadedHulls.Count),("planes",planeCount),("meshes",meshJson.GetArrayLength()),("meshVertices",vertexCount),("triangles",loadedTriangles.Count)})if(counts.GetProperty(name).GetInt32()!=actual)throw Invalid("count mismatch: "+name);return new(map,loadedHulls.ToArray(),loadedTriangles.ToArray(),attrs);
 }catch(InvalidDataException){throw;}catch(Exception e)when(e is JsonException or InvalidOperationException or KeyNotFoundException or FormatException or OverflowException or ArgumentException){throw Invalid("malformed data");}}
 int Build(int start,int count){Box bounds=primitives[start].Bounds;for(int i=start+1;i<start+count;i++)bounds=Box.Union(bounds,primitives[i].Bounds);int index=nodes.Count;nodes.Add(new(bounds,start,count,-1,-1));if(count<=8)return index;var extent=bounds.Max-bounds.Min;int axis=extent.X>=extent.Y&&extent.X>=extent.Z?0:extent.Y>=extent.Z?1:2;static float Axis(Vector3 v,int axis)=>axis==0?v.X:axis==1?v.Y:v.Z;Array.Sort(primitives,start,count,Comparer<Primitive>.Create((a,b)=>Axis(a.Bounds.Center,axis).CompareTo(Axis(b.Bounds.Center,axis))));int half=count/2,left=Build(start,half),right=Build(start+half,count-half);nodes[index]=new(bounds,start,0,left,right);return index;}
 static double Dot(Vector3 a,Vector3 b)=>(double)a.X*b.X+(double)a.Y*b.Y+(double)a.Z*b.Z;
 static bool Slab(Box box,Vector3 from,Vector3 delta){double lo=0,hi=1;for(int axis=0;axis<3;axis++){double f=axis==0?from.X:axis==1?from.Y:from.Z,d=axis==0?delta.X:axis==1?delta.Y:delta.Z,min=axis==0?box.Min.X:axis==1?box.Min.Y:box.Min.Z,max=axis==0?box.Max.X:axis==1?box.Max.Y:box.Max.Z;if(Math.Abs(d)<1e-12){if(f<min-1e-5||f>max+1e-5)return false;continue;}double a=(min-f)/d,b=(max-f)/d;if(a>b)(a,b)=(b,a);lo=Math.Max(lo,a);hi=Math.Min(hi,b);if(lo>hi+1e-10)return false;}return true;}
 public TraceResult TraceSegment(Vector3 from,Vector3 to){if(!Finite(from)||!Finite(to))throw new ArgumentException("Segment coordinates must be finite and bounded.");var delta=to-from;double length=Math.Sqrt(Dot(delta,delta));var intervals=new List<HullInterval>();var hits=new List<MeshHit>();if(length<1e-9||nodes.Count==0)return new(intervals,hits,0);int candidates=0;var stack=new Stack<int>();stack.Push(0);while(stack.Count>0){var node=nodes[stack.Pop()];if(!Slab(node.Bounds,from,delta))continue;if(node.Count==0){stack.Push(node.Left);stack.Push(node.Right);continue;}for(int i=node.Start;i<node.Start+node.Count;i++){var primitive=primitives[i];if(!Slab(primitive.Bounds,from,delta))continue;candidates++;if(primitive.IsHull){var h=hulls[primitive.Index];double enter=0,exit=double.PositiveInfinity;bool inside=true,endsInside=true,tangent=false,miss=false;Vector3 entryNormal=default,exitNormal=default;foreach(var p in h.Planes){var normal=new Vector3(p.X,p.Y,p.Z);double distance=Dot(normal,from)-p.W,denominator=Dot(normal,delta);if(distance>1e-6)inside=false;if(Dot(normal,to)-p.W>=-1e-6)endsInside=false;if(Math.Abs(denominator)<1e-10){if(distance>1e-6){miss=true;break;}if(Math.Abs(distance)<=1e-6)tangent=true;continue;}double t=-distance/denominator;if(denominator<0){if(t>enter){enter=t;entryNormal=normal;}}else if(t<exit){exit=t;exitNormal=normal;}if(enter>exit+1e-10){miss=true;break;}}if(!miss&&enter<=1&&exit>=0){bool exitWithinSegment=exit>=0&&exit<=1;enter=Math.Clamp(enter,0,1);exit=Math.Clamp(exit,0,1);tangent|=exit-enter<=1e-10;bool hasPhysicalExit=exitWithinSegment&&!tangent;if(!hasPhysicalExit)exitNormal=default;intervals.Add(new(enter,exit,tangent?0:(exit-enter)*length,from+delta*(float)enter,from+delta*(float)exit,entryNormal,exitNormal,inside,endsInside,hasPhysicalExit,tangent,primitive.Index,h.SurfaceHash,h.Attribute,attributes[h.Attribute]));}}
 else{var triangle=triangles[primitive.Index];var edge1=triangle.B-triangle.A;var edge2=triangle.C-triangle.A;var p=Vector3.Cross(delta,edge2);double determinant=Dot(edge1,p),scale=Math.Sqrt(Dot(edge1,edge1)*Dot(edge2,edge2))*length;if(Math.Abs(determinant)<=Math.Max(1e-12,scale*1e-10))continue;double inverse=1/determinant;var offset=from-triangle.A;double u=Dot(offset,p)*inverse;if(u < -1e-7||u>1+1e-7)continue;var q=Vector3.Cross(offset,edge1);double v=Dot(delta,q)*inverse;if(v < -1e-7||u+v>1+1e-7)continue;double t=Dot(edge2,q)*inverse;if(t < -1e-9||t>1+1e-9)continue;t=Math.Clamp(t,0,1);hits.Add(new(t,from+delta*(float)t,triangle.Normal,Dot(triangle.Normal,delta)<0,triangle.SurfaceHash,triangle.Attribute,attributes[triangle.Attribute],triangle.MeshIndex,triangle.TriangleIndex));}}}
 intervals.Sort((a,b)=>a.EntryT.CompareTo(b.EntryT));hits.Sort((a,b)=>a.T.CompareTo(b.T));var distinct=new List<MeshHit>();double epsilon=1e-4/length;foreach(var hit in hits){bool duplicate=false;for(int j=distinct.Count-1;j>=0&&hit.T-distinct[j].T<=epsilon;j--)if(distinct[j].MeshIndex==hit.MeshIndex&&distinct[j].SurfaceHash==hit.SurfaceHash&&distinct[j].CollisionAttributeIndex==hit.CollisionAttributeIndex&&Vector3.Dot(distinct[j].Normal,hit.Normal)>1-1e-6f){duplicate=true;break;}if(!duplicate)distinct.Add(hit);}return new(intervals,distinct,candidates);}
}

